-- Reapply the frozen position defaults after making tenant discovery safe for
-- the non-BYPASSRLS migration owner. V35 was intentionally idempotent, but a
-- fresh Flyway connection could see zero tenant rows while tenant FORCE RLS was
-- active and therefore complete without publishing any profile. This migration
-- repeats the guarded V35 logic and restores FORCE RLS in the same transaction.

-- Publish the frozen position/function defaults only for untouched blank
-- V1 drafts generated by V33.  This migration is deliberately fail-closed:
-- custom drafts, published history, hotel overrides and hotel applicability
-- changes are never rewritten.

-- Split the cross-hotel cockpit from the single-hotel cockpit.  The original
-- dashboard.hotel permission remains the prerequisite for opening one hotel;
-- dashboard.operations is independently configurable for regional aggregation.
INSERT INTO permission (
    code, resource, action, description, delegable_to_position, function_category
) VALUES (
    'dashboard.operations', 'dashboard', 'operations', '查看授权范围的区域多门店驾驶舱', true, 'DASHBOARD'
)
ON CONFLICT (code) DO UPDATE
SET resource = EXCLUDED.resource,
    action = EXCLUDED.action,
    description = EXCLUDED.description,
    delegable_to_position = true,
    function_category = 'DASHBOARD';

