    position_code VARCHAR(64) PRIMARY KEY,
    authorization_scope_type VARCHAR(24) NOT NULL
        CHECK (authorization_scope_type IN ('SELF', 'ORG_UNIT', 'ORG_TREE', 'TENANT'))
) ON COMMIT DROP;

